// The charter a request session launches with (#one-request-one-debug-session) — kept out of the
// component file so it is directly testable and so the mount stays a component-only module.
export { requestPaneId } from "@/shared/lib/session/requestSpawn";

// ── The debug-session constants (#debug-nodes-hang-off-the-session-that-filed-them) ────────────────
//
// These used to live in `DebugSessionMount`, the STANDING debug session's component. That session and
// its node are gone — every request draws its own — but the two constants below are not about the
// standing session at all: they are what ANY debug session launches with. They moved here, beside the
// only thing that still uses them, rather than being kept alive by a component that no longer mounts.
//
// `DEBUG_START_PROMPT` did NOT move. It was the standing session's queue-serving half ("claim the next
// request"), and a per-request session must never claim — the app claimed for it, and a second claim
// would take a request another session already holds.

export const DEBUG_INIT_CMD = "claude";

/** The shared DEBUG-session prose: who the session is, what it may touch, and the workflow + git rules
 *  every one of them follows. It deliberately says NOTHING about how the session gets its work — the
 *  charter below supplies that, naming the one request this session was spawned for.
 *
 *  ⚠️ ITS SCOPE IS THE WHOLE APP, and this prose said otherwise for a long time. It opened with "your
 *  job: improve the `bsc ui` surface so the Design Studio's designer session never needs permissions
 *  outside it" — true when the queue was the designer's alone, and false since every studio, the
 *  architect and the fleet started filing onto it. Measured on the live queue when this was fixed: the
 *  open requests named `bsc navigate`, `bsc ui`, `bsc graph`, `bsc plan` and `bsc fleet`, resolving to
 *  five different crates. The prompt even contradicted itself one sentence later ("implement the fix
 *  in the owning crate"), which is the instruction that was always right.
 *
 *  Keep it surface-agnostic. Naming a crate here re-scopes every debug session to whichever gap
 *  happened to be common the week it was written. */
export const DEBUG_ROLE_PROMPT =
  "You are the base-studio-code DEBUG session. You have full read/write access to THIS repository and " +
  "run the normal dev workflow. Your job is the WHOLE APPLICATION'S `bsc` surface: every session that " +
  "hits a wall files onto one queue — the architect, the designer, the librarian, the sound designer, " +
  "a director, a dev session — so a request can name any noun and land in any crate. Take the request " +
  "you were given and follow it to whatever owns it. " +
  "Reproduce the cited `bsc` command, implement the fix IN THE OWNING CRATE with tests, verify the gate " +
  "with `npm run gate -- --full`, then `bsc request resolve <id> --note \"<what changed>\"` and " +
  "rebuild the sidecar with " +
  "`cargo build --bin bsc` (the DEV profile — release is the slow one and nothing local needs it). The app " +
  "re-stages that binary and retires its warm `bsc` on its own the moment your request resolves, so the fix " +
  "is live for the next call with NO restart — do not ask for one. " +
  "Track the work the way every slice here is tracked: `bsc plan add` the item if there is not one " +
  "already, `bsc plan change new <ref>` at the START, and `bsc plan change gate <ref> <name> <result>` " +
  "with what each gate ACTUALLY did. " +
  "Work in a git worktree at the REPO ROOT as `wt-<short>` (nested there it needs no npm install, and " +
  "`.claude/worktrees/` is write-denied mid-session) on a branch off develop. " +
  "THIS REPO IS LOCAL-FIRST: never push, never open a PR, never write to GitHub — integration is a " +
  "local `git merge --no-ff` into develop once the work is verified. NEVER commit to develop or main " +
  "directly, and never switch the main checkout off develop.";

/** What a request session needs to know about the request it was spawned for. A subset of the
 *  `bsc request` row (snake_case from the Rust store), so a caller passes the row through. */
export interface RequestBrief {
  id: number;
  /** WHO filed it — the filing session's pane id (#debug-request-carries-its-origin), e.g.
   *  `designer-studio:react`. Absent when the request was filed outside a session. */
  origin?: string | null;
  /** The label form of the request, always populated by the store (explicit `--title`, else derived
   *  from the text). */
  display_title?: string | null;
}

/** The ROLES a studio pane id can name, longest first so `sound-designer` is matched before `designer`
 *  could ever claim its tail. Each maps to how the charter says it in prose. */
const ORIGIN_ROLES: readonly (readonly [string, string])[] = [
  ["sound-designer", "sound designer"],
  ["designer", "designer"],
  ["librarian", "librarian"],
  ["architect", "architect"],
  ["integrator", "integrator"],
];

/** The human name for a filing session's pane id — `design-studio:designer-react` → "the react designer".
 *
 *  READ THE TAIL, NOT THE STUDIO. The first version of this split on `:` and treated the left half as the
 *  role (`<role>-studio`), which is wrong for every session: the studio is named for the SURFACE
 *  (`design-studio`, `algorithms-studio`, `teams-studio`, `sound-studio`, `integration-studio`) and the
 *  role lives in the tail (`designer-react`, `librarian-typescript`, `architect`). It cost nothing to
 *  write and would have mislabelled every request, because the tests quoted the same invented shape.
 *
 *  Derived rather than looked up: the id is the only thing the request carries, and importing the session
 *  registry here would make the charter depend on a store-touching module to phrase one sentence. An
 *  unrecognised shape falls back to the raw id — a project director's `myproject:director` reads as
 *  itself, which is more use to a debug session than no attribution at all. */
export function originLabel(origin: string): string {
  const tail = (origin ?? "").split(":")[1] ?? "";
  for (const [role, human] of ORIGIN_ROLES) {
    if (tail === role) return `the ${human}`;
    if (tail.startsWith(`${role}-`)) return `the ${tail.slice(role.length + 1)} ${human}`;
  }
  return origin;
}

/**
 * The charter for the session working request `req`.
 *
 * It names the request instead of telling the session to go and find one. Under #3535 every pool
 * session launched generic and ran `bsc request claim` on startup, because a slot had no request until
 * it won the race; now the APP claims first and spawns a session for what it got, so the session starts
 * already knowing its job. That removes the whole warming/losing-the-race state — and with it the
 * reaper that existed to clean up after it.
 *
 * The session does NOT claim: its request is already `claimed` (the app did that atomically to obtain
 * the id), and one session exists per request by construction, so there is nothing left to race for.
 *
 * IT ALSO NAMES WHO FILED IT (#debug-request-carries-its-origin). A debug session is spawned BY a
 * studio session hitting a gap, and the fix is only right if it unblocks THAT session's actual workflow
 * — a `bsc ui` gap the React designer hit is a different fix from the same message arriving from
 * nowhere. The origin is on the request, so the charter states it and tells the session it may reply on
 * the thread; without that the relationship exists only in the graph, where the session working the
 * request cannot see it.
 *
 * The closing instruction is deliberate and carried over unchanged: a request must never be left open
 * with no explanation — "filed and silently unworked" is the failure this whole feature exists to
 * remove — and the resolve note IS the change log the maintainer reads back.
 */
export function requestCharter(req: RequestBrief): string {
  const { id } = req;
  const title = req.display_title?.trim();
  const origin = req.origin?.trim();
  const heading = title ? `YOUR REQUEST IS #${id} — "${title}".` : `YOUR REQUEST IS #${id}.`;
  const filedBy = origin
    ? `It was filed by ${originLabel(origin)} (\`${origin}\`) — a session that hit this gap in real work, ` +
      `not a hypothetical. Fix it so THAT session is unblocked: the failing command on the request is what ` +
      `it actually tried. If you need something from them, or the fix changes how the surface is used, ` +
      `reply on the request's thread — \`bsc request note ${id} "<what you found>" --from debugger\` — which ` +
      `they read back with \`bsc request get ${id}\`.\n\n`
    : "";
  return (
    `${DEBUG_ROLE_PROMPT}\n\n` +
    `${heading} It is already claimed for you — do not run \`bsc request claim\`. ` +
    `Read it, then work ONLY that one:\n` +
    `  bsc request get ${id}\n\n` +
    filedBy +
    `Reproduce the failing command, implement the fix in the owning crate with tests, verify the gate, ` +
    `then:\n` +
    `  bsc request resolve ${id} --note "<what you changed>"\n\n` +
    `The note is the change log — always leave one, even if it turns out NOT to be a defect (resolve it ` +
    `anyway with a note saying why; a request must never be left open with no explanation). Then STOP — ` +
    `your session is done and will be closed once #${id} reads resolved.`
  );
}

